NAME = 'NorSMB: Studentmållagsbibelen frå 1921'
BOOK = 'II Peter'

CHAPTERS = {
    1: {
        1: 'Simeon Peter, Jesu Kristi tenar og apostel, til deim som hev fenge same dyre tru som me ved vår Gud og frelsar Jesu Kristi rettferd:',
        2: 'Nåde og fred vere med dykk i rikt mål, med di de kjenner Gud og Jesus, vår Herre!',
        3: 'Etter som hans guddomlege magt hev gjeve oss alt som høyrer til liv og gudlegdom, ved kunnskapen um honom som kalla oss ved sin eigen herlegdom og si kraft,',
        4: 'og dermed hev gjeve oss dei største og dyraste lovnader, for at de ved deim skulde verta luthavande i guddomleg natur, med di de flyr frå den tyning i verdi som kjem av lysti:',
        5: 'so gjer dykk og just difor all umak, og vis i trui dykkar dygd, og i dygdi skynsemd,',
        6: 'og i skynsemdi fråhald, og i fråhaldet tolmod, og i tolmodet gudlegdom,',
        7: 'og i gudlegdomen broderkjærleik, og i broderkjærleiken kjærleik til alle.',
        8: 'For når desse ting finst hjå dykk og fær veksa, då viser dei at de ikkje er yrkjelause eller fruktlause i kunnskapen um vår Herre Jesus Kristus.',
        9: 'For den som ikkje hev desse ting, han er blind, dimsynt og hev gløymt reinsingi frå sine fyrre synder.',
        10: 'Difor, brør, legg so mykje meir vinn på å gjera dykkar kall og utveljing fast; for når de gjer desse ting, skal de ikkje nokon gong snåva.',
        11: 'For soleis skal det rikleg verta gjeve dykk inngang i vår Herre og frelsar Jesu Kristi ævelege rike.',
        12: 'Difor kjem eg alltid til å minna dykk um dette, endå de veit det og er grunnfeste i den sanning som er hjå dykk.',
        13: 'Like vel held eg det for rett å vekkja dykk ved påminning, so lenge eg er i denne hytta,',
        14: 'sidan eg veit at eg brått skal leggja ned hytta mi, so som og vår Herre Jesus Kristus hev varsla meg.',
        15: 'Men eg vil og leggja vinn på at de alltid etter min burtgang kann minnast dette.',
        16: 'For det var ikkje klokt uttenkte eventyr me fylgde, då me kunngjorde dykk vår Herre Jesu Kristi magt og tilkoma, men me hadde vore augvitne til hans storvelde.',
        17: 'For han fekk æra og herlegdom av Gud Fader, ei slik røyst kom til honom frå den høgste herlegdomen: «Dette er son min, som eg elskar, som eg hev hugnad i.»',
        18: 'Og denne røysti høyrde me koma frå himmelen, då me var saman med honom på det heilage fjellet.',
        19: 'Og dess fastare hev me det profetiske ordet, og de gjer vel i å agta på det som på eit ljos som skin på ein myrk stad, til dess dagen lyser fram, og morgonstjerna renn upp i hjarto dykkar,',
        20: 'men di de fyrst og fremst veit dette, at inkje profetord i skrifti er gjeve til eigi tyding.',
        21: 'For aldri er noko profetord framkome av mannevilje; men dei heilage Guds menner tala, drivne av den Heilage Ande.',
    },
    2: {
        1: 'Men det stod og falske profetar fram hjå folket, liksom det og hjå dykk skal koma falske lærarar, som skal lura inn ranglæror som fører til fortaping, med di dei jamvel neittar den Herre som kjøpte deim, og fører yver seg sjølve ei brå fortaping.',
        2: 'Og mange skal fylgja deim i deira used, og for deira skuld skal sanningsvegen verta spotta,',
        3: 'og av havesykja skal dei med uppdikta ord nytta dykk ut til vinning. Men domen er frå gamall tid ikkje yrkjelaus mot deim, og deira fortaping søv ikkje.',
        4: 'For so visst som Gud ikkje sparde englar då dei synda, men støytte deim ned i avgrunnen og gav deim yver til myrke holor i varetekt til dom,',
        5: 'og ikkje sparde den gamle verdi, men heldt uppe rettferds-forkynnaren Noah sjølv-åttande, då han førde storflodi yver ei verd av ugudlege,',
        6: 'og lagde byarne Sodoma og Gomorra i oska og fordømde deim til undergang og dermed sette deim til fyredøme på dei ugudlege i framtidi,',
        7: 'og fria ut den rettferdige Lot, som leid under den skamlause åtferdi av dei ugudlege',
        8: '- for den rettferdige som budde imillom deim, leid dagstødt pinsla i si rettferdige sjæl ved dei lovlause gjerningar som han såg og høyrde -',
        9: 'so veit Herren å fria dei gudlege ut or freisting, men halda dei urettferdige i varetekt med refsing til domedag,',
        10: 'mest deim som fer etter kjøtet i urein lyst og vanvyrder herredøme. Dei sjølvgode vågehalsar! Dei skjelv ikkje ved å spotta høge magter,',
        11: 'medan då englar, som er større i styrke og magt, ikkje ber fram for Herren nokon spottande dom imot deim.',
        12: 'Men desse, liksom vitlause dyr, av naturi fødde til fanging og undergang, dei skal, av di dei spottar det dei ikkje kjenner, gagna under ved si eigi uferd',
        13: 'og få urettferds løn. Dei set si lyst i å bruka dagen til kjæla; dei utskjemmor og skamflekkjer; dei kræser seg ved sitt svik når dei held gilde med dykk.',
        14: 'Augo hev dei som er fyllte av skjøkja og umetteleg i synd; dei forlokkar ustøde sjæler; dei hev eit hjarta som er upptamt i havesykja, dei forbanningsborn!',
        15: 'Dei hev vike av frå den beine vegen og fare vilt, med di dei hev fylgt Bileam Beorssons veg, han som elska urettferds løn',
        16: 'og fekk refsing for sitt eige brot: eit umælande klyvdyr tala med mannemæle til honom og hindra profeten i hans uvitingskap.',
        17: 'Desse er vatslause kjeldor, skodda som vert drivi av stormvind; til deim er kolmyrket ferdigt.',
        18: 'For med di dei talar skrøytande, tome ord, forlokkar dei i kjøtslyster ved ukjurskap deim som nett hev flytt ifrå deim som fer i villa,',
        19: 'med di dei lovar deim fridom, dei som sjølve er trælar under tjon; for det som ein ligg under for, det hev han og vorte træl for.',
        20: 'For um dei hev flytt ifrå ureinskapen i verdi med di dei hev lært å kjenna vår Herre og frelsar Jesus Kristus, og so atter vert innfløkte i henne og ligg under, då hev det siste vorte verre med deim enn det fyrste.',
        21: 'For det var betre for deim at dei ikkje hadde kjent rettferds veg, enn at dei kjende honom og so vende seg burt att frå det heilage bodet som var yvergjeve deim.',
        22: 'Det hev gjenge deim etter det sanne ordtøket: «Ein hund vendar atter til si eigi spya,» og: «Ei lauga su velter seg i søyla.»',
    },
    3: {
        1: 'Dette er no alt det andre brevet eg skriv til dykk, de kjære, og i deim ved påminning vekkjer dykkar reine hug',
        2: 'til å minnast dei ord som fyrr er tala av dei heilage profetar, og bodet frå Herren og frelsaren som apostlarne dykkar hev forkynt,',
        3: 'med di de fyrst og fremst veit dette, at i dei siste dagar skal det koma spottarar med spott, som gjeng etter sine eigne lyster',
        4: 'og segjer: «Kvar er lovnaden um hans tilkoma? For ifrå den tid då federne sovna av, stend alt so som frå upphavet av skapningen.»',
        5: 'For dei som segjer so, gløymer at himlar var det frå gamall tid og ei jord som hadde vorte til ut av vatn og gjenom vatn ved Guds ord,',
        6: 'og dermed gjekk og den dåverande verdi under i vatsflaumen.',
        7: 'Men dei noverande himlar og jordi er ved det same ordet sparde til elden, og upphaldne til den dagen då dei ugudlege menneskje skal verta dømde og fortapte.',
        8: 'Men dette eine må de ikkje sleppa or syne, mine kjære, at ein dag er for Herren som tusund år, og tusund år som ein dag.',
        9: 'Herren er ikkje langdrygjen med lovnaden, so som sume held det for ei drygjing; men han er langmodig med dykk, då han ikkje vil at nokon skal verta fortapt, men at alle skal koma til umvending.',
        10: 'Men Herrens dag skal koma som ein tjuv; då skal himlarne forgangast med dundrane ljom, og himmelklotarne skal koma i brand og verta uppløyste, og jordi og alle verk på henne verta uppbrende.',
        11: 'Då no alt dette vert uppløyst, kor må ikkje de då stræva etter heilag ferd og gudlegt liv,',
        12: 'medan de ventar og skundar på at Guds dag skal koma, som skal gjera at himlarne vert uppløyste i eld, og himmelklotarne kjem i brand og brånar!',
        13: 'Men me ventar etter hans lovnad nye himlar og ei ny jord, der rettferd bur.',
        14: 'Difor, mine kjære, då de ventar dette, so legg vinn på at de kann verta funne utan flekk og lyte for hans åsyn i fred!',
        15: 'Og agta det langmod vår Herre viser, som ei frelsa, som og vår kjære bror Paulus hev skrive til dykk etter den visdom som han hev fenge,',
        16: 'liksom og i alle sine brev når han i deim talar um desse ting; i deim er det noko som er vandt å skynda, som ulærde og ustøde mistyder, liksom dei og gjer med dei andre skrifterne, til sin eigen undergang.',
        17: 'So må då de, mine kjære, som fyreåt veit dette, vara dykk, so de ikkje skal verta dregne med i villa av dei ugudlege og falla frå dykkar eigen faste grunn!',
        18: 'Men veks i nåde og kjennskap til vår Herre og frelsar Jesus Kristus! Honom vere æra både no og til æveleg tid! Amen.',
    },
}
